14	export default function AdjustStockForm({
15	  itemName,
16	  currentStock,
17	  unit,
18	  action,
19	}: {
20	  itemName: string;
21	  currentStock: number;
22	  unit?: string;
23	  action: (newStock: number, reason: string) => Promise<{ error: string | null }>;
24	}) {
25	  const router = useRouter();
26	  const [open, setOpen] = useState(false);
27	  const [newStock, setNewStock] = useState(String(currentStock));
28	  const [reason, setReason] = useState(REASONS[0]);
29	  const [error, setError] = useState<string | null>(null);
30	  const [submitting, setSubmitting] = useState(false);
31	  const unitSuffix = unit ? ` ${unit}` : "";
32	
33	  if (!open) {
34	    return (
35	      <button
36	        onClick={() => setOpen(true)}
37	        className="shrink-0 text-xs font-medium text-zinc-400 hover:text-brand-600 hover:underline"
38	      >
39	        Sesuaikan stok
40	      </button>
41	    );
42	  }
43	
44	  async function handleSubmit() {
45	    setError(null);
46	    setSubmitting(true);
47	    const result = await action(Number(newStock), reason);
48	    setSubmitting(false);
49	
50	    if (result.error) {
51	      setError(result.error);
52	      return;
53	    }
54	
55	    setOpen(false);
56	    router.refresh();
57	  }
58	
59	  return (
60	    <div className="mt-2 w-full rounded-xl border border-zinc-200 bg-zinc-50 p-3">
61	      <p className="text-xs text-zinc-500">
62	        Sesuaikan stok <span className="font-medium text-zinc-700">{itemName}</span> — stok
63	        sistem saat ini {currentStock}
64	        {unitSuffix}.
65	      </p>
66	      <div className="mt-2 space-y-2">
67	        <div>
68	          <label className="mb-1 block text-xs font-medium text-zinc-600">
69	            Stok fisik sebenarnya{unitSuffix}
70	          </label>
71	          <input
72	            type="number"
73	            min="0"
74	            step="any"
75	            value={newStock}
76	            onChange={(e) => setNewStock(e.target.value)}
77	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
78	          />
79	        </div>
80	        <div>
81	          <label className="mb-1 block text-xs font-medium text-zinc-600">Alasan</label>
82	          <select
83	            value={reason}
84	            onChange={(e) => setReason(e.target.value)}
85	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
86	          >
87	            {REASONS.map((r) => (
88	              <option key={r} value={r}>
89	                {r}
90	              </option>
91	            ))}
92	          </select>
93	        </div>
94	
95	        {error && (
96	          <p className="rounded-lg bg-red-50 px-2 py-1.5 text-xs text-red-600">{error}</p>
97	        )}
98	
99	        <div className="flex gap-2">
100	          <button
101	            onClick={handleSubmit}
102	            disabled={submitting}
103	            className="flex-1 rounded-lg bg-brand-600 py-2 text-xs font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
104	          >
105	            {submitting ? "Menyimpan…" : "Simpan"}
106	          </button>
107	          <button
108	            type="button"
109	            onClick={() => {
110	              setOpen(false);
111	              setError(null);
112	            }}
113	            className="rounded-lg px-3 py-2 text-xs font-medium text-zinc-500 hover:text-zinc-700"
114	          >
115	            Batal
116	          </button>
117	        </div>
118	      </div>
119	    </div>
120	  );
121	}
